  "stuSess.penaltyChoiceRefundDesc": "לקבלת החזר (€{amount}), יש לפנות לכתובת info@tutlio.lt. אם התשלום בוצע בכרטיס, ייתכן שתהליך ההחזר יתחיל אוטומטית דרך Stripe.",
  "stuSess.creditAvailable": "זיכוי זמין",
  "stuSess.payWithCredit": "תשלום באמצעות זיכוי",
  "stuSess.creditAppliedSuccess": "זיכוי בסך €{amount} נוסף ליתרה שלך וינוצל אוטומטית בשיעור הבא.",
  "stuSess.refundContactNote": "לקבלת החזר, יש לפנות לכתובת <a href=\"mailto:info@tutlio.lt\" class=\"text-amber-800 underline\">info@tutlio.lt</a>.",
  "stuSess.refundSuccessStripeNote": "<p class=\"text-emerald-900 text-sm mb-2\">יש שאלות או בעיות? אפשר לפנות לכתובת <a href=\"mailto:info@tutlio.lt\" class=\"underline font-medium\">info@tutlio.lt</a>.</p><p class=\"font-semibold text-emerald-900\">תהליך ההחזר שלך התחיל דרך Stripe.</p><p class=\"text-emerald-800 mt-1\">החזרים לכרטיס מתקבלים בדרך כלל בתוך כ־<strong>5–10 ימי עסקים</strong> (הזמן עשוי להשתנות בין בנקים). אם ההחזר לא מתקבל בפרק הזמן המקובל, יש לשלוח הודעה לכתובת <a href=\"mailto:info@tutlio.lt\" class=\"text-emerald-900 underline font-medium\">info@tutlio.lt</a>.</p>",
  "stuSess.refundSuccessManualTutor": "<p>נראה ששיעור זה לא שולם דרך Stripe ב־Tutlio (למשל, שולם בהעברה בנקאית או במזומן). אין כאן אפשרות להחזר אוטומטי.</p><p class=\"mt-2\">לתיאום החזר, יש לפנות למורה <strong>{tutor}</strong> — באמצעות כתובת האימייל או פרטי הקשר המופיעים בהזמנות שלך, או פרטים שנמסרו ישירות מהמורה.</p>",
  "stuSess.refundSuccessManualOrg": "<p>נראה ששיעור זה לא שולם דרך Stripe ב־Tutlio (למשל, שולם בהעברה בנקאית או במזומן). אין כאן אפשרות להחזר אוטומטי.</p><p class=\"mt-2\">מכיוון שהלמידה מתבצעת דרך ארגון, יש לפנות ל<strong>מנהל הארגון</strong> (דרך המורה או באמצעות פרטי הקשר שפרסם הארגון).</p>",
