  "landing.faq.whatIsQ": "מהי Tutlio?",
  "landing.faq.whatIsA": "Tutlio היא פלטפורמה לניהול הוראה פרטית שעוזרת למורים פרטיים ולבתי ספר להוראה פרטית לנהל תיאום שיעורים, תשלומים, תקשורת עם תלמידים ומעקב שיעורים ממקום אחד.",
  "landing.faq.whoForQ": "למי Tutlio מיועדת?",
  "landing.faq.whoForA": "Tutlio מיועדת למורים פרטיים, למורים למוזיקה, למדריכי שפות, למורים למתמטיקה, לבתי ספר להוראה פרטית ולמרכזי חינוך בכל גודל.",
  "landing.faq.waitlistQ": "איך פועלת רשימת ההמתנה לתלמידים?",
  "landing.faq.waitlistA": "כשתלמיד מבטל שיעור, חלון הזמן שהתפנה מוצע אוטומטית לתלמידים ברשימת ההמתנה. הראשון שמאשר מקבל את המקום — כך מורים לא מאבדים הכנסה מביטולים.",
  "landing.faq.freeTrialQ": "יש ניסיון חינם?",
  "landing.faq.freeTrialA": "כן! כל חשבון חדש מקבל אוטומטית 7 ימים בחינם — אין צורך בקוד. לא נגבה תשלום בתקופת הניסיון, ואפשר לבטל בכל עת.",
  "landing.faq.languagesQ": "באילו שפות Tutlio תומכת?",
  "landing.faq.languagesA": "Tutlio זמינה ב־{count} שפות: {languages}.",
  "landing.faqTitle": "שאלות נפוצות",
  "landing.feature.digital-business-card": "כרטיס ביקור דיגיטלי",
  "landing.feature.digital-business-cardDesc": "שתפו עמוד מקצועי אחד שבו תלמידים יכולים להכיר אתכם, לראות מחירים וזמינות מעודכנים ולבקש שיעור מיד.",
  "featuresIndex.newBadge": "חדש",
  "feature.digital-business-card.pageTitle": "כרטיס ביקור דיגיטלי שהופך עניין לבקשות לשיעורים",
  "feature.digital-business-card.pageDesc": "תנו לכל תלמיד פוטנציאלי קישור אחד מוקפד עם הסיפור שלכם, השיעורים, המחירים, הביקורות והזמינות המעודכנת. הם בוחרים שיעור ומועד מיד — ואתם מפסיקים לאבד פניות בשרשורי הודעות ארוכים.",
  "feature.digital-business-card.detailsTitle": "כל מה שתלמיד פוטנציאלי צריך כדי לומר כן",
  "feature.digital-business-card.oneLink": "קישור אחד לכל עסק ההוראה הפרטית שלכם",
  "feature.digital-business-card.oneLinkDesc": "החליפו פרופילים מפוזרים ברשתות חברתיות, מחירונים והודעות הזמנה בעמוד אחד שאפשר לשתף בכל מקום.",
  "feature.digital-business-card.liveAvailability": "זמינות שנשארת מעודכנת",
  "feature.digital-business-card.liveAvailabilityDesc": "המועדים הפנויים מגיעים ישירות מיומן Tutlio שלכם, כך שלקוחות מבקשים רק חלונות זמן שבהם אתם באמת רוצים ללמד.",
  "feature.digital-business-card.instantEnquiries": "בקשות לשיעורים בזמן שאתם מלמדים",
  "feature.digital-business-card.instantEnquiriesDesc": "הורה או תלמיד בוחרים שיעור, סוג ומועד, ואז משאירים פרטים. הבקשה המלאה מגיעה אליכם בלי שיחת תיאום.",
  "feature.digital-business-card.professionalBrand": "רושם ראשוני מקצועי",
  "feature.digital-business-card.professionalBrandDesc": "הציגו תמונה, גישת הוראה, מקצועות לימוד, מחירים, ביקורות מאומתות וצבעי מותג בעמוד שנראה מצוין בכל טלפון.",
  "feature.digital-business-card.faq.whatShowsQ": "מה אפשר להציג בכרטיס הביקור הדיגיטלי שלי?",
  "feature.digital-business-card.faq.whatShowsA": "אפשר להציג היכרות אישית, מקצועות לימוד, סוגי שיעורים, מחירים ציבוריים, חלונות זמן פנויים ביומן, מיקום, שפות, קישורים חברתיים וביקורות תלמידים מאומתות.",
  "feature.digital-business-card.faq.howBookingWorksQ": "האם הלקוח מזמין מיד שיעור מאושר?",
  "feature.digital-business-card.faq.howBookingWorksA": "הלקוח בוחר שיעור ומועד פנוי, ואז שולח בקשת הזמנה מלאה. הבקשה מתקבלת ב־Tutlio, ואפשר לאשר את התלמיד החדש לפני שהשיעור נוסף למערכת השעות שלך.",
  "feature.digital-business-card.faq.whereShareQ": "איפה כדאי לשתף את העמוד?",
  "feature.digital-business-card.faq.whereShareA": "אפשר להשתמש בו ב־Instagram, ב־TikTok, בקבוצות Facebook, במודעות, בחתימות אימייל, בהודעות ובקודי QR. קישור אחד נשאר מעודכן גם כשהמחירים או היומן משתנים.",
  "feature.digital-business-card.demo.eyebrow": "תצוגת לקוח אינטראקטיבית",
  "feature.digital-business-card.demo.title": "נסו את חוויית ההזמנה",
  "feature.digital-business-card.demo.desc": "בחרו שיעור ומועד למטה. זה התהליך הפשוט שלקוח חדש מקבל דרך הקישור ששותף.",
  "feature.digital-business-card.demo.profile": "מורה למתמטיקה · כיתות 9–12",
  "feature.digital-business-card.demo.available": "מקבלים תלמידים חדשים",
  "feature.digital-business-card.demo.pickLesson": "1. בחירת שיעור",
