  "feature.digital-business-card.demo.exam": "הכנה ממוקדת לבחינה",
  "feature.digital-business-card.demo.examDesc": "90 דקות · הכנה ממוקדת",
  "feature.digital-business-card.demo.trial": "שיחת היכרות",
