  "landing.leadSuccess": "תודה! ניצור קשר בהמשך.",
  "orgTutorPolicy.title": "כללים פנימיים למורים",
  "orgTutorPolicy.intro": "יש לעיין בכללים הפנימיים של הארגון לפני השימוש בפלטפורמה.",
  "orgTutorPolicy.acceptBtn": "הבנתי",
  "orgTutorPolicy.viewBtn": "הצגת הכללים הפנימיים",
  "orgTutorPolicy.s1Title": "1. הוראות כלליות",
  "orgTutorPolicy.s1Body": "כללים אלה מסדירים את השימוש שלך בפלטפורמת Tutlio (״הפלטפורמה״) כמורה או כמורה פרטי (״המורה״). הוזמנת להשתמש בפלטפורמה על ידי סוכנות החינוך, בית הספר או מרכז ההוראה הפרטית שאותם אתה מייצג (״הארגון״). MB Tutlio מספקת תחזוקה טכנית ותמיכה לפלטפורמה. השימוש בחשבון שלך מהווה הסכמה לכללים אלה ולמדיניות הפרטיות.",
  "orgTutorPolicy.s2Title": "2. ניהול חשבון ומערכות שעות",
  "orgTutorPolicy.s2Intro": "הפלטפורמה נועדה לחסוך לך זמן בתיאום מועדי שיעורים עם תלמידים.",
  "orgTutorPolicy.s2Link": "קישור ייחודי: מוקצה לך קישור אישי להזמנת שיעורים (לפי המקצועות שאתה מלמד), שבו התלמידים משתמשים לקביעת שיעורים.",
  "orgTutorPolicy.s2Calendar": "סנכרון יומן: הזמינות שלך תלויה ישירות בחיבור ל־Google Calendar (סנכרון ב־2 כיוונים). באחריותך האישית לוודא שהזמן הפנוי המוצג ביומן מדויק ומעודכן. הפלטפורמה לא תאפשר לתלמידים להזמין מועדים המסומנים כתפוסים ביומן שלך.",
  "orgTutorPolicy.s2Security": "אבטחת חשבון: החשבון שלך אישי. עליך לשמור על פרטי ההתחברות ולא לשתף אותם עם צדדים שלישיים.",
  "orgTutorPolicy.s3Title": "3. ביטולי שיעורים ורשימת המתנה",
  "orgTutorPolicy.s3Intro": "הפלטפורמה עוזרת לנצל את מערכת השעות שלך ולהימנע מחלונות זמן ריקים:",
  "orgTutorPolicy.s3Auto": "אם תלמיד מבטל שיעור, הפלטפורמה שולחת אוטומטית הודעה (SMS/אימייל) לתלמידים אחרים ברשימת ההמתנה שלך, ומציעה את המקום שהתפנה. אין צורך בפעולה נוספת מצדך.",
